package capability

import (
	"regexp"
	"sort"
	"strings"
	"testing"
)

func TestSchemaMarkdown(t *testing.T) {
	ex, err := Examples("../../../render/testdata/root")
	if err != nil {
		t.Fatal(err)
	}
	pages := SchemaMarkdown(WithExamples(Schemas(Default()), ex))
	var keys []string
	for k := range pages {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	if got := strings.Join(keys, " "); got != "app.md env-vars.md owners.md stage.md target.md" {
		t.Fatalf("pages: %s", got)
	}
	app := pages["app.md"]
	for _, want := range []string{
		"<!-- generated by gcd docs; do not edit -->\n# app\n",
		"capabilities/{cap}/apps/*/app.yml",
		"| Field | Type | Description |\n|---|---|---|\n",
		"| `stages.<stage>.targets.<target>.replicas` | int | ",
		"| `env.<KEY>` | str | ",
		"| `envFrom[]` | str | ",
	} {
		if !strings.Contains(app, want) {
			t.Errorf("app.md lacks %q", want)
		}
	}
	if !strings.HasPrefix(app, "<!-- generated by gcd docs; do not edit -->\n# app\n") {
		t.Errorf("app.md starts %.80q", app)
	}
	row := func(field string) string {
		for _, l := range strings.Split(app, "\n") {
			if strings.HasPrefix(l, "| `"+field+"` |") {
				return l
			}
		}
		t.Fatalf("no row for %s", field)
		return ""
	}
	if r := row("deployWith"); !strings.Contains(r, "<br>Values: `argocd`, `gha`") {
		t.Errorf("deployWith row: %s", r)
	}
	if r := row("sourceRepo"); !strings.Contains(r, "| str | **Required.** GitHub") || !strings.Contains(r, "<br>Pattern: `^[A-Za-z0-9_.-]+") {
		t.Errorf("sourceRepo row: %s", r)
	}
	if r := row("replicas"); strings.Contains(r, "Required") || strings.Contains(r, "only.") {
		t.Errorf("replicas row: %s", r)
	}
	if r := row("workflow.ref"); strings.Contains(r, "Pattern") {
		t.Errorf("workflow.ref: non-empty pattern shown: %s", r)
	}
	if r := row("image"); !strings.Contains(r, "<br>Example: [") {
		t.Errorf("image row: %s", r)
	}
	if strings.Count(row("replicas"), " | ") != 2 {
		t.Errorf("replicas row not 3 cols: %s", row("replicas"))
	}
	tgt := pages["target.md"]
	if !strings.Contains(tgt, "terraform state backend. *TERRAFORM only.*") {
		t.Errorf("target.md lacks platform note:\n%s", tgt)
	}
	link := regexp.MustCompile(`\[` + "`" + `payments/apps/[^` + "`" + `]+:(\d+)` + "`" + `\]\(\.\./\.\./platform/render/testdata/root/capabilities/payments/apps/[^)#]+#L(\d+)\)`)
	m := link.FindStringSubmatch(row("image"))
	if m == nil || m[1] != m[2] {
		t.Errorf("image example link: %s", row("image"))
	}
	env := pages["env-vars.md"]
	if !strings.Contains(env, "| `<KEY>` | str | ") {
		t.Errorf("env-vars.md root key row missing:\n%s", env)
	}
}

func TestSchemaMarkdownEscapes(t *testing.T) {
	docs := []SchemaDoc{{Kind: "k", File: "f.yml", Desc: "d", Fields: []FieldDoc{
		{Name: "x", Type: "str", Desc: "a|b\nc", Pattern: "x|y"},
		{Name: "y", Type: "str", Desc: "repo, <owner>/<name>"},
	}}}
	p := SchemaMarkdown(docs)["k.md"]
	for _, want := range []string{`a\|b c`, "`x\\|y`", "repo, &lt;owner&gt;/&lt;name&gt;"} {
		if !strings.Contains(p, want) {
			t.Errorf("lacks %q:\n%s", want, p)
		}
	}
}
